import React, { useState } from 'react';

const UserInfoTab = ({ userInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  // 수정 시 사용할 데이터, userInfo를 기반으로 초기화!
  const [formData, setFormData] = useState({
    ...userInfo,
    // 비밀번호 필드 추가 (기존 userInfo에는 없을 수 있으니 초기값 설정)
    password: '',
    confirmPassword: '',
  }); 

  // 입력 필드 변경 핸들러
  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  // 폼 제출 핸들러
  const handleSubmit = (e) => {
    e.preventDefault();

    // 비밀번호 유효성 검사 (새 비밀번호 필드가 비어있지 않을 경우에만 검사)
    if (formData.password || formData.confirmPassword) { // 둘 중 하나라도 입력됐으면 검사
      if (formData.password !== formData.confirmPassword) {
        alert('비밀번호와 비밀번호 확인이 일치하지 않아! 다시 확인해줘. 🧐');
        return;
      }
      // 비밀번호가 입력되었다면, 기존 비밀번호와 동일한지 백엔드에서 확인하는 로직도 추가하면 좋겠지?
    }

    // 여기에 실제 백엔드 회원 정보 수정 API 호출 로직을 넣어줘!
    // formData를 백엔드로 전송하면 돼. (비밀번호는 변경이 필요한 경우에만 전송하도록 백엔드에서 처리)
    alert('회원 정보가 성공적으로 수정되었어! 🎉 (API 연동 필요)');
    console.log('수정된 정보:', formData);
    setIsEditing(false); // 수정 완료 후 보기 모드로 전환
    // 수정이 완료되면, 최신 userInfo를 다시 불러오거나 formData로 userInfo를 업데이트해주는 로직도 필요할 수 있어!
  };

  // 회원 탈퇴 핸들러
  const handleWithdrawal = () => {
    // 경고창을 더 명확하게!
    if (window.confirm('🚨 정말로 회원 탈퇴하시겠습니까? 모든 정보가 영구적으로 삭제돼! 😱')) {
      // 여기에 실제 백엔드 회원 탈퇴 API 호출 로직을 넣어줘!
      alert('회원 탈퇴가 완료되었어. 그동안 이용해줘서 고마워! 👋 (API 연동 필요)');
      // 탈퇴 후 로그인 페이지 등으로 리디렉션하는 로직도 추가해줘.
    }
  };

  return (
    // MyPage.css에 정의된 스타일을 그대로 사용하도록 클래스명 유지
    <div className="tab-content-section user-info-tab">
      <h3 className="tab-content-title">회원 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        // 회원 정보 보기 탭
        <>
          {/* 아이디 필드 추가 - userInfo에 'userId'가 있다고 가정 */}
          <div className="info-item">
            <span className="info-label">아이디</span>
            <span className="info-value">{userInfo.userId || '정보 없음'}</span> 
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value">{userInfo.email || '정보 없음'}</span>
          </div>
          {/* 닉네임 필드 추가 - userInfo에 'nickname'이 있다고 가정 */}
          <div className="info-item">
            <span className="info-label">닉네임</span>
            <span className="info-value">{userInfo.nickname || '정보 없음'}</span> 
          </div>
          {/* 회원 등급과 가입일은 기존대로 유지 */}
          <div className="info-item">
            <span className="info-label">회원 등급</span>
            <span className="info-value">{userInfo.membershipLevel || '정보 없음'}</span>
          </div>
          <div className="info-item">
            <span className="info-label">가입일</span>
            <span className="info-value">{userInfo.registeredDate || '정보 없음'}</span>
          </div>
          {/* action-button 클래스는 MyPage.css에 정의되어 있음 */}
          <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정 ✏️</button>
        </>
      ) : (
        // 회원 정보 수정 탭
        <form onSubmit={handleSubmit}>
          <div className="info-item">
            <label className="info-label" htmlFor="email">이메일</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="info-value-input"
              required 
            />
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="nickname">닉네임</label>
            <input
              type="text"
              id="nickname"
              name="nickname"
              value={formData.nickname}
              onChange={handleChange}
              className="info-value-input" 
              required 
            />
          </div>
          {/* 비밀번호 변경 필드 추가 */}
          <div className="info-item">
            <label className="info-label" htmlFor="password">새 비밀번호</label>
            <input
              type="password"
              id="password"
              name="password"
              value={formData.password}
              onChange={handleChange}
              className="info-value-input" 
              placeholder="변경할 비밀번호를 입력해줘"
              autoComplete="new-password" 
            />
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="confirmPassword">새 비밀번호 확인</label>
            <input
              type="password"
              id="confirmPassword"
              name="confirmPassword"
              value={formData.confirmPassword}
              onChange={handleChange}
              className="info-value-input"
              placeholder="비밀번호를 다시 입력해줘"
              autoComplete="new-password" 
            />
          </div>
          
          <div className="button-group" style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '30px' }}> {/* 인라인 스타일로 버튼 그룹 정렬 */}
            <button type="submit" className="action-button">저장 ✅</button>
            <button type="button" className="action-button" onClick={() => setIsEditing(false)}>취소 ↩️</button>
            {/* delete-button 클래스는 MyPage.css에 정의되어 있음 */}
            <button type="button" className="action-button delete-button" onClick={handleWithdrawal}>회원 탈퇴 🗑️</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default UserInfoTab;
